import 'package:zerowaste_grocer/features/catalog/domain/models/product.dart';

/// Status of an AI replenishment order recommendation.
enum RecommendationStatus {
  pending,
  approved,
  overridden,
}

/// Explainable AI factor contributing to the replenishment recommendation.
class XaiDriver {
  const XaiDriver({
    required this.label,
    required this.impactPct,
  });

  final String label;
  final double impactPct;
}

/// AI replenishment recommendation generated by the backend model.
class Recommendation {
  const Recommendation({
    required this.productId,
    required this.productName,
    required this.category,
    required this.currentStock,
    required this.safetyStock,
    required this.predictedDemand,
    required this.recommendedQty,
    required this.approvedQty,
    required this.status,
    required this.xaiReason,
    required this.xaiDrivers,
  });

  final int productId;
  final String productName;
  final ProductCategory category;
  final int currentStock;
  final int safetyStock;
  final int predictedDemand;
  final int recommendedQty;
  final int approvedQty;
  final RecommendationStatus status;
  final String xaiReason;
  final List<XaiDriver> xaiDrivers;

  Recommendation copyWith({
    int? productId,
    String? productName,
    ProductCategory? category,
    int? currentStock,
    int? safetyStock,
    int? predictedDemand,
    int? recommendedQty,
    int? approvedQty,
    RecommendationStatus? status,
    String? xaiReason,
    List<XaiDriver>? xaiDrivers,
  }) {
    return Recommendation(
      productId: productId ?? this.productId,
      productName: productName ?? this.productName,
      category: category ?? this.category,
      currentStock: currentStock ?? this.currentStock,
      safetyStock: safetyStock ?? this.safetyStock,
      predictedDemand: predictedDemand ?? this.predictedDemand,
      recommendedQty: recommendedQty ?? this.recommendedQty,
      approvedQty: approvedQty ?? this.approvedQty,
      status: status ?? this.status,
      xaiReason: xaiReason ?? this.xaiReason,
      xaiDrivers: xaiDrivers ?? this.xaiDrivers,
    );
  }
}

/// Individual item modification within an order approval request.
class ApprovalItem {
  const ApprovalItem({
    required this.productId,
    required this.finalQty,
    this.overrideReason,
  });

  final int productId;
  final int finalQty;
  final String? overrideReason;
}

/// Payload sent to approve and finalize replenishment recommendations.
class ApprovalRequest {
  const ApprovalRequest({
    required this.storeId,
    required this.items,
  });

  final int storeId;
  final List<ApprovalItem> items;
}
